#include "live_mesh_read.hpp"
#include <filesystem>
#include <regex>
#include <unordered_map>
template<class T>std::vector<T> copy_span(Reader& p,Span span,std::size_t limit){if(span.count>limit||!pointer(span.pointer))throw std::runtime_error("Invalid typed geometry extent");std::vector<T> out(span.count);SIZE_T got{};const auto bytes=out.size()*sizeof(T);if(bytes&&(!ReadProcessMemory(p.h,reinterpret_cast<void*>(span.pointer),out.data(),bytes,&got)||got!=bytes))throw std::runtime_error("Typed geometry read failed");return out;}
struct CachedMesh {std::uint32_t index{};std::string digest;};
int main(int argc,char** argv)try{
 if(argc!=4)throw std::invalid_argument("Usage: tm2020_live_mesh_capture manifest inventory.jsonl output-directory");tm2020::live::ReadOnlyObserver identity(argv[1]);Reader p{OpenProcess(PROCESS_VM_READ|PROCESS_QUERY_LIMITED_INFORMATION,FALSE,identity.process_id())};if(!p.h)throw std::runtime_error("Read-only open denied");verify_pinned_build(p);std::ifstream inventory(argv[2]);if(!inventory)throw std::runtime_error("No typed mesh inventory");std::string line;std::getline(inventory,line);if(line.find("\"pid\":"+std::to_string(identity.process_id())+",")==std::string::npos)throw std::runtime_error("Stale mesh inventory PID");const std::regex mesh_pattern("\\\"mesh\\\":\\\"(0x[0-9a-f]+)\\\"");std::vector<std::uintptr_t> addresses;while(std::getline(inventory,line)){std::smatch found;if(std::regex_search(line,found,mesh_pattern))addresses.push_back(std::stoull(found[1],nullptr,16));}
 const auto directory=std::filesystem::path(argv[3]);std::filesystem::create_directories(directory);std::ofstream report(directory/"meshes.jsonl");std::unordered_map<std::uintptr_t,CachedMesh> meshes;std::size_t cooked_exact{},trees_exact{},triangles{},vertices{},geometry_bytes{};
 for(auto address:addresses){try{Mesh header{};if(!p.get(address,header)||header.type!=7)throw std::runtime_error("Mesh binding changed");auto v=copy_span<std::array<float,3>>(p,header.vertices,1000000);auto t=copy_span<CookedTriangle>(p,header.cooked_triangles,2000000);auto tree=copy_span<AabbNode>(p,header.tree,4000000);for(const auto& point:v)if(!finite(point))throw std::runtime_error("Invalid mesh vertex");std::vector<IndexedTriangle> raw;for(const auto& tri:t){if(!finite(tri.normal)||!std::isfinite(tri.plane_constant))throw std::runtime_error("Invalid cooked triangle");for(auto index:tri.vertices)if(index>=v.size())throw std::runtime_error("Triangle index exceeds mesh");raw.push_back({tri.vertices,tri.surface_id,0});}for(const auto& n:tree)if((n.packed&1)&&(n.packed>>1)>=t.size())throw std::runtime_error("Tree leaf exceeds triangle count");query_aabb_tree(tree,{0,0,0},{1000000,1000000,1000000});
  const auto cooked=cook_triangles(v,raw);bool exact=true;for(std::size_t j=0;j<t.size();j++)if(std::memcmp(&cooked[j],&t[j],30)){exact=false;break;}cooked_exact+=exact;const auto rebuilt=build_aabb_tree(triangle_aabbs(v,raw));const bool tree_exact=rebuilt.size()==tree.size()&&std::memcmp(rebuilt.data(),tree.data(),tree.size()*sizeof(AabbNode))==0;trees_exact+=tree_exact;Mesh after{};if(!p.get(address,after)||std::memcmp(&header,&after,sizeof(header)))throw std::runtime_error("Mesh header changed during capture");
  geometry_bytes+=16+v.size()*12+t.size()*32+tree.size()*28;if(geometry_bytes>512ull*1024*1024)throw std::runtime_error("Geometry cache exceeds 512 MiB bound");
  const auto index=std::uint32_t(meshes.size());const auto path=directory/("mesh-"+std::to_string(index)+".tmmesh");std::ofstream data(path,std::ios::binary);const std::array<std::uint32_t,4> meta{0x314d5254,std::uint32_t(v.size()),std::uint32_t(t.size()),std::uint32_t(tree.size())};data.write(reinterpret_cast<const char*>(meta.data()),sizeof(meta));data.write(reinterpret_cast<const char*>(v.data()),v.size()*sizeof(v[0]));for(auto& tri:t)tri.reserved=0;data.write(reinterpret_cast<const char*>(t.data()),t.size()*sizeof(t[0]));data.write(reinterpret_cast<const char*>(tree.data()),tree.size()*sizeof(tree[0]));data.flush();if(!data)throw std::runtime_error("Cannot save local mesh cache");data.close();const auto digest=tm2020::live::file_sha256(path);meshes.emplace(address,CachedMesh{index,digest});triangles+=t.size();vertices+=v.size();report<<"{\"mesh\":\"0x"<<std::hex<<address<<std::dec<<"\",\"cacheIndex\":"<<index<<",\"vertices\":"<<v.size()<<",\"triangles\":"<<t.size()<<",\"treeNodes\":"<<tree.size()<<",\"cookerDefinedBytesExact\":"<<(exact?"true":"false")<<",\"treeRebuildBitExact\":"<<(tree_exact?"true":"false")<<",\"sha256\":\""<<digest<<"\"}\n";
 }catch(const std::exception& e){std::cerr<<"Rejected mesh 0x"<<std::hex<<address<<std::dec<<' '<<e.what()<<'\n';}}
 report.flush();if(!report)throw std::runtime_error("Cannot write mesh cache audit");std::cout<<"LIVE_GEOMETRY meshes="<<meshes.size()<<" vertices="<<vertices<<" triangles="<<triangles<<" exact_cookers="<<cooked_exact<<" exact_trees="<<trees_exact<<std::endl;
 std::array<bool,65536> bloom{};for(const auto& [address,m]:meshes)bloom[address&65535]=true;std::set<std::uintptr_t> seen;std::ofstream instances(directory/"instances.jsonl");instances<<std::setprecision(9);const auto scanned=scan(p,8192,[&](std::uintptr_t base,std::span<const std::byte> data){for(std::size_t at=0;at+56<=data.size();at+=8){std::uintptr_t shape{};std::memcpy(&shape,data.data()+at,8);if(!bloom[shape&65535])continue;const auto it=meshes.find(shape);if(it==meshes.end())continue;MeshTransform transform{};std::memcpy(&transform,data.data()+at+8,48);if(!finite(transform.rotation)||!finite(transform.translation))continue;bool valid=true;for(unsigned a=0;a<3;a++)for(unsigned b=0;b<3;b++){const auto& r=transform.rotation;const float dot=(r[a*3]*r[b*3]+r[a*3+1]*r[b*3+1])+r[a*3+2]*r[b*3+2];if(std::abs(dot-(a==b?1.f:0.f))>2e-4)valid=false;}if(!valid||!seen.insert(base+at).second)continue;instances<<"{\"candidate\":\"0x"<<std::hex<<base+at<<std::dec<<"\",\"meshIndex\":"<<it->second.index<<",\"rotation\":[";for(unsigned j=0;j<9;j++){if(j)instances<<',';instances<<transform.rotation[j];}instances<<"],\"translation\":[";for(unsigned j=0;j<3;j++){if(j)instances<<',';instances<<transform.translation[j];}instances<<"],\"worldPlacementVerified\":false}\n";}});
 instances.flush();if(!instances)throw std::runtime_error("Cannot save typed instance hypotheses");std::ofstream summary(directory/"summary.json");summary<<"{\"schema\":\"tm2020_live_geometry_cache_v1\",\"pid\":"<<identity.process_id()<<",\"readOnly\":true,\"meshes\":"<<meshes.size()<<",\"vertices\":"<<vertices<<",\"triangles\":"<<triangles<<",\"exactCookers\":"<<cooked_exact<<",\"exactTreeRebuilds\":"<<trees_exact<<",\"typedInstanceHypotheses\":"<<seen.size()<<",\"scannedMB\":"<<scanned/1048576<<",\"worldPlacementVerified\":false,\"completeMapCollisionVerified\":false}\n";std::cout<<"PASS LIVE_GEOMETRY_CACHE instances="<<seen.size()<<" world_placement_unqualified=true\n";
return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}
